package routing

// costClassRank maps cost class to numeric rank (lower = cheaper).
var costClassRank = map[string]int{
	"local":        0,
	"cheap":        1,
	"medium":       2,
	"expensive":    3,
	"experimental": -1,
	"":             2, // unknown = medium
}

const StickyAffinityBonus = 250.0
const unknownUtilizationPenalty = 0.0
const unknownPerformancePenalty = 0.0

// scorePolicy returns a score for a candidate under the named profile.
// Higher is better.
//
// Routing priority policy (ported from DDx routing.go):
//   - cheap: local + low-cost preferred; subscription-within-quota next.
//   - standard: balanced; light local/subscription preference to avoid spend.
//   - smart: quality first; cloud capability wins; no local bonus.
//
// The policy is profile-aware AND provider-aware via providerBias hooks
// supplied by the caller (cooldown demotion, observation perf bias,
// provider-affinity bias).
func scorePolicy(profile string, cand candidateInternal) float64 {
	total := 0.0
	for _, component := range scoreComponents(profile, cand) {
		total += component
	}
	return total
}

func scoreComponents(profile string, cand candidateInternal) map[string]float64 {
	components := map[string]float64{
		"base":                100,
		"cost":                0,
		"deployment_locality": 0,
		"quota_health":        0,
		"utilization":         0,
		"performance":         0,
		"power":               0,
		"context_headroom":    0,
		"sticky_affinity":     0,
	}
	base := 100.0
	cr := costClassRank[cand.CostClass]
	withinQuota := cand.IsSubscription && cand.QuotaOK
	add := func(name string, value float64) {
		if value == 0 {
			return
		}
		components[name] += value
	}

	switch profile {
	case "cheap":
		if cand.CostClass == "local" {
			base += 40
			add("deployment_locality", 40)
		} else if withinQuota {
			base += 20
			add("quota_health", 20)
		}
		base -= float64(cr) * 30
		add("cost", -float64(cr)*30)

	case "standard":
		if cand.CostClass == "local" {
			base += 25
			add("deployment_locality", 25)
		} else if withinQuota {
			base += 15
			add("quota_health", 15)
		}
		base -= float64(cr) * 10
		add("cost", -float64(cr)*10)

	case "smart":
		// Quality first; higher cost rank approximates higher capability.
		base += float64(cr) * 20
		add("cost", float64(cr)*20)
		if withinQuota {
			base += 5
			add("quota_health", 5)
		}

	default:
		// Treat unspecified as standard.
		if cand.CostClass == "local" {
			base += 25
			add("deployment_locality", 25)
		} else if withinQuota {
			base += 15
			add("quota_health", 15)
		}
		base -= float64(cr) * 10
		add("cost", -float64(cr)*10)
	}

	// Provider preference bias.
	switch cand.ProviderPreference {
	case "local-first", "":
		if cand.CostClass == "local" {
			base += 30
			add("deployment_locality", 30)
		}
	case "subscription-first":
		if cand.IsSubscription && cand.QuotaOK {
			base += 30
			add("quota_health", 30)
		}
	}

	// Quota signals.
	if cand.IsSubscription {
		// Stale quota penalty.
		if cand.QuotaStale {
			base -= 15
			add("quota_health", -15)
		}

		// Trend-based adjustments.
		switch cand.QuotaTrend {
		case "exhausting":
			base -= 40
			add("quota_health", -40)
		case "burning":
			base -= 20
			add("quota_health", -20)
		case "healthy":
			base += 10
			add("quota_health", 10)
		}

		// Quota near-limit penalty (>= 80% used).
		if cand.QuotaPercentUsed >= 80 {
			penalty := float64(cand.QuotaPercentUsed-80) * 2
			base -= penalty
			add("quota_health", -penalty)
		}
	}

	// Historical success-rate adjustment (only when sufficient samples).
	if cand.HistoricalSuccessRate >= 0 {
		switch {
		case cand.HistoricalSuccessRate >= 0.8:
			base += 20
			add("quota_health", 20)
		case cand.HistoricalSuccessRate < 0.5:
			base -= 30
			add("quota_health", -30)
		}
	}
	if cand.ProviderSuccessRate >= 0 {
		switch {
		case cand.ProviderSuccessRate >= 0.8:
			base += 25
			add("quota_health", 25)
		case cand.ProviderSuccessRate < 0.5:
			base -= 35
			add("quota_health", -35)
		}
	}

	// Cooldown demotion: candidate has had recent failures.
	if cand.InCooldown {
		base -= 50
		add("quota_health", -50)
	}

	// Sticky affinity is a bonus after eligibility, not a hard pin.
	if cand.StickyMatch {
		base += StickyAffinityBonus
		add("sticky_affinity", StickyAffinityBonus)
	}

	// Utilization pressure can outweigh stickiness when the chosen server is
	// already busy or saturated.
	// Unknown or stale utilization is treated explicitly. Current policy is
	// neutral rather than a hidden zero-value bonus.
	if cand.EndpointSaturated {
		base -= 300
		add("utilization", -300)
	}
	if cand.EndpointLoad > 0 {
		loadPenalty := cand.EndpointLoad * 10
		if cand.EndpointLoadFresh {
			loadPenalty *= 2
		} else {
			loadPenalty += unknownUtilizationPenalty
		}
		if loadPenalty > 60 {
			loadPenalty = 60
		}
		base -= loadPenalty
		add("utilization", -loadPenalty)
	} else if !cand.EndpointLoadFresh {
		base -= unknownUtilizationPenalty
		add("utilization", -unknownUtilizationPenalty)
	}

	// Provider affinity: explicit provider pins are filtered before scoring;
	// this bonus only affects the ordering among still-eligible candidates
	// that share the pinned provider identity.
	if cand.ProviderAffinityMatch {
		base += 15
		add("deployment_locality", 15)
	}

	if cand.Power > 0 {
		base += float64(cand.Power) * 12
		add("power", float64(cand.Power)*12)
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens > 0 {
		costPenalty := cand.CostUSDPer1kTokens * 500
		if costPenalty > 60 {
			costPenalty = 60
		}
		base -= costPenalty
		add("cost", -costPenalty)
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens == 0 {
		switch {
		case cand.CostClass == "local":
			base += 15
			add("cost", 15)
		case cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80:
			base += 15
			add("quota_health", 15)
		}
	}
	if cand.Power >= 9 && cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80 {
		base += 20
		add("power", 20)
	}

	// Context headroom is a ranking signal for otherwise eligible candidates.
	// A larger spare window gives the model more room for completion and tool
	// overhead, so reward it modestly without overpowering the primary policy.
	if cand.ContextHeadroom > 0 {
		headroomBonus := float64(cand.ContextHeadroom) / 1000.0
		if headroomBonus > 30 {
			headroomBonus = 30
		}
		base += headroomBonus
		add("context_headroom", headroomBonus)
	}

	// Observation-derived perf bias.
	havePerfSignal := false
	if cand.ObservedTokensPerSec > 0 {
		// Small additive bonus, scaled.
		bonus := cand.ObservedTokensPerSec / 100.0
		base += bonus
		add("performance", bonus)
		havePerfSignal = true
	}
	if cand.ObservedLatencyMS > 0 {
		// Latency is a tiebreaker-scale signal: faster endpoints gain a small
		// bonus while very slow endpoints receive little benefit.
		bonus := 1000.0 / cand.ObservedLatencyMS
		base += bonus
		add("performance", bonus)
		havePerfSignal = true
	}
	if !havePerfSignal {
		// Missing performance data is deliberate; current policy is neutral.
		base -= unknownPerformancePenalty
		add("performance", -unknownPerformancePenalty)
	}
	if cand.CostClass == "experimental" {
		base -= 75
		add("deployment_locality", -75)
	}

	// base tracks the implicit profile baseline so the components sum to the
	// same total as scorePolicy's legacy behavior.
	components["base"] = base - (components["cost"] + components["deployment_locality"] + components["quota_health"] + components["sticky_affinity"] + components["utilization"] + components["power"] + components["context_headroom"] + components["performance"])
	return components
}

package routing

import "testing"

func TestResolvePenalizesUnknownUtilizationAndPerformance(t *testing.T) {
	in := Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "fiz",
				CostClass:           "local",
				AutoRoutingEligible: true,
				Available:           true,
				ExactPinSupport:     true,
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{Name: "known", DefaultModel: "model-a", CostClass: "local", SupportsTools: true},
					{Name: "unknown", DefaultModel: "model-a", CostClass: "local", SupportsTools: true},
				},
			},
		},
		ModelEligibility: func(model string) (ModelEligibility, bool) {
			if model != "model-a" {
				return ModelEligibility{}, false
			}
			return ModelEligibility{Power: 7, AutoRoutable: true}, true
		},
		EndpointLoadResolver: func(provider, endpoint, model string) (EndpointLoad, bool) {
			if provider != "known" || model != "model-a" {
				return EndpointLoad{}, false
			}
			return EndpointLoad{NormalizedLoad: 0.1, UtilizationFresh: true}, true
		},
		ObservedSpeedTPS: map[string]float64{
			ProviderModelKey("known", "", "model-a"): 90,
		},
		ObservedLatencyMS: map[string]float64{
			ProviderModelKey("known", "", "model-a"): 100,
		},
	}

	dec, err := Resolve(Request{Harness: "fiz", Model: "model-a"}, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if len(dec.Candidates) != 2 {
		t.Fatalf("Candidates=%d, want 2", len(dec.Candidates))
	}
	var known, unknown Candidate
	for _, c := range dec.Candidates {
		switch c.Provider {
		case "known":
			known = c
		case "unknown":
			unknown = c
		}
	}
	if known.Provider != "known" || unknown.Provider != "unknown" {
		t.Fatalf("candidates=%+v, want known and unknown providers", dec.Candidates)
	}
	if known.Score <= unknown.Score {
		t.Fatalf("known score %.1f should beat unknown score %.1f", known.Score, unknown.Score)
	}
	if known.ScoreComponents == nil || unknown.ScoreComponents == nil {
		t.Fatalf("score components must be populated: known=%v unknown=%v", known.ScoreComponents, unknown.ScoreComponents)
	}
	for _, key := range []string{"base", "cost", "deployment_locality", "quota_health", "utilization", "performance", "power", "context_headroom", "sticky_affinity"} {
		if _, ok := known.ScoreComponents[key]; !ok {
			t.Fatalf("known score components missing %q: %+v", key, known.ScoreComponents)
		}
		if _, ok := unknown.ScoreComponents[key]; !ok {
			t.Fatalf("unknown score components missing %q: %+v", key, unknown.ScoreComponents)
		}
	}
	if known.Utilization <= 0 {
		t.Fatalf("known utilization component=%v, want positive known load", known.Utilization)
	}
	if unknown.Utilization != 0 {
		t.Fatalf("unknown utilization component=%v, want 0 for unknown load", unknown.Utilization)
	}
	if known.ScoreComponents["utilization"] == 0 {
		t.Fatalf("known utilization score component=%v, want explicit known-load adjustment", known.ScoreComponents["utilization"])
	}
	if unknown.ScoreComponents["utilization"] != 0 {
		t.Fatalf("unknown utilization score component=%v, want 0 for unknown load", unknown.ScoreComponents["utilization"])
	}
	if known.ScoreComponents["performance"] <= 0 {
		t.Fatalf("known performance score component=%v, want positive known performance", known.ScoreComponents["performance"])
	}
	if unknown.ScoreComponents["performance"] != 0 {
		t.Fatalf("unknown performance score component=%v, want 0 for unknown performance", unknown.ScoreComponents["performance"])
	}
	if known.StickyAffinity != 0 || unknown.StickyAffinity != 0 {
		t.Fatalf("unexpected sticky affinity components: known=%v unknown=%v", known.StickyAffinity, unknown.StickyAffinity)
	}
	if dec.Provider != "known" {
		t.Fatalf("winner provider=%q, want known", dec.Provider)
	}
}

func TestResolveReportsStickyAffinityComponentWhenStickyKeyMatches(t *testing.T) {
	in := Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "fiz",
				CostClass:           "local",
				AutoRoutingEligible: true,
				Available:           true,
				ExactPinSupport:     true,
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{Name: "server-a", ServerInstance: "desk-a", DefaultModel: "model-a", CostClass: "local", SupportsTools: true},
					{Name: "server-b", ServerInstance: "desk-b", DefaultModel: "model-a", CostClass: "local", SupportsTools: true},
				},
			},
		},
		ModelEligibility: func(model string) (ModelEligibility, bool) {
			if model != "model-a" {
				return ModelEligibility{}, false
			}
			return ModelEligibility{Power: 7, AutoRoutable: true}, true
		},
		EndpointLoadResolver: func(provider, endpoint, model string) (EndpointLoad, bool) {
			if provider != "server-a" && provider != "server-b" {
				return EndpointLoad{}, false
			}
			if endpoint == "desk-a" {
				return EndpointLoad{NormalizedLoad: 0.2, UtilizationFresh: true}, true
			}
			return EndpointLoad{NormalizedLoad: 0.4, UtilizationFresh: true}, true
		},
		StickyServerInstanceResolver: func(stickyKey string) (string, bool) {
			if stickyKey == "session-1" {
				return "desk-a", true
			}
			return "", false
		},
	}

	dec, err := Resolve(Request{Harness: "fiz", Model: "model-a", CorrelationID: "session-1"}, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if dec.ServerInstance != "desk-a" {
		t.Fatalf("server_instance=%q, want desk-a", dec.ServerInstance)
	}
	var sticky Candidate
	for _, c := range dec.Candidates {
		if c.ServerInstance == "desk-a" {
			sticky = c
			break
		}
	}
	if sticky.ServerInstance != "desk-a" {
		t.Fatalf("sticky candidate not found: %+v", dec.Candidates)
	}
	if sticky.StickyAffinity != StickyAffinityBonus {
		t.Fatalf("sticky affinity component=%v, want %v", sticky.StickyAffinity, StickyAffinityBonus)
	}
	if sticky.ScoreComponents["sticky_affinity"] != StickyAffinityBonus {
		t.Fatalf("sticky score component=%v, want %v", sticky.ScoreComponents["sticky_affinity"], StickyAffinityBonus)
	}
	if sticky.Utilization <= 0 {
		t.Fatalf("sticky utilization component=%v, want positive load", sticky.Utilization)
	}
}

package routing

import (
	"testing"
	"time"
)

func TestResolveStickyServerInstanceAcrossModelChanges(t *testing.T) {
	now := time.Date(2026, 5, 6, 12, 0, 0, 0, time.UTC)
	var stickyServerInstance string

	baseInputs := Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "fiz",
				Surface:             "embedded-openai",
				CostClass:           "local",
				AutoRoutingEligible: true,
				Available:           true,
				ExactPinSupport:     true,
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{
						Name:           "alpha",
						ServerInstance: "server-a",
						CostClass:      "local",
						DiscoveredIDs:  []string{"model-a", "model-b"},
						SupportsTools:  true,
					},
					{
						Name:           "beta",
						ServerInstance: "server-b",
						CostClass:      "local",
						DiscoveredIDs:  []string{"model-a", "model-b"},
						SupportsTools:  true,
					},
				},
			},
		},
		Now: now,
		EndpointLoadResolver: func(provider, endpoint, model string) (EndpointLoad, bool) {
			if provider != "alpha" && provider != "beta" {
				return EndpointLoad{}, false
			}
			switch model {
			case "model-a":
				switch endpoint {
				case "server-a":
					return EndpointLoad{NormalizedLoad: 0.1, UtilizationFresh: true}, true
				case "server-b":
					return EndpointLoad{NormalizedLoad: 1.0, UtilizationFresh: true}, true
				}
			case "model-b":
				switch endpoint {
				case "server-a":
					return EndpointLoad{NormalizedLoad: 1.0, UtilizationFresh: true}, true
				case "server-b":
					return EndpointLoad{NormalizedLoad: 0.1, UtilizationFresh: true}, true
				}
			}
			return EndpointLoad{}, false
		},
		StickyServerInstanceResolver: func(stickyKey string) (string, bool) {
			if stickyServerInstance == "" {
				return "", false
			}
			return stickyServerInstance, true
		},
	}

	first, err := Resolve(Request{Harness: "fiz", Model: "model-a", CorrelationID: "bead-lease-1"}, baseInputs)
	if err != nil {
		t.Fatalf("Resolve(model-a): %v", err)
	}
	if first.ServerInstance != "server-a" {
		t.Fatalf("first server_instance=%q, want server-a", first.ServerInstance)
	}
	if !first.Candidates[0].Eligible {
		t.Fatalf("first top candidate must be eligible: %#v", first.Candidates[0])
	}
	stickyServerInstance = first.ServerInstance

	second, err := Resolve(Request{Harness: "fiz", Model: "model-b", CorrelationID: "bead-lease-1"}, baseInputs)
	if err != nil {
		t.Fatalf("Resolve(model-b with sticky lease): %v", err)
	}
	if second.ServerInstance != "server-a" {
		t.Fatalf("sticky decision server_instance=%q, want server-a", second.ServerInstance)
	}
	if second.Candidates[0].ServerInstance != "server-a" {
		t.Fatalf("sticky top candidate=%#v, want server-a", second.Candidates[0])
	}
	var sticky, nonSticky Candidate
	for _, c := range second.Candidates {
		switch c.ServerInstance {
		case "server-a":
			sticky = c
		case "server-b":
			nonSticky = c
		}
	}
	if sticky.ServerInstance != "server-a" || nonSticky.ServerInstance != "server-b" {
		t.Fatalf("second candidates=%#v, want both server-a and server-b", second.Candidates)
	}
	if nonSticky.Utilization >= sticky.Utilization {
		t.Fatalf("non-sticky utilization=%v, want lower than sticky utilization=%v", nonSticky.Utilization, sticky.Utilization)
	}
	if sticky.Score <= nonSticky.Score {
		t.Fatalf("sticky score=%.2f should beat the merely better non-sticky score=%.2f", sticky.Score, nonSticky.Score)
	}

	controlInputs := baseInputs
	controlInputs.StickyServerInstanceResolver = nil
	control, err := Resolve(Request{Harness: "fiz", Model: "model-b"}, controlInputs)
	if err != nil {
		t.Fatalf("Resolve(model-b without sticky): %v", err)
	}
	if control.ServerInstance != "server-b" {
		t.Fatalf("control server_instance=%q, want server-b without sticky affinity", control.ServerInstance)
	}

	saturatedInputs := baseInputs
	saturatedInputs.StickyServerInstanceResolver = baseInputs.StickyServerInstanceResolver
	saturatedInputs.EndpointLoadResolver = func(provider, endpoint, model string) (EndpointLoad, bool) {
		if provider != "alpha" && provider != "beta" {
			return EndpointLoad{}, false
		}
		switch model {
		case "model-b":
			switch endpoint {
			case "server-a":
				return EndpointLoad{NormalizedLoad: 100, UtilizationFresh: true, UtilizationSaturated: true}, true
			case "server-b":
				return EndpointLoad{NormalizedLoad: 0.1, UtilizationFresh: true}, true
			}
		}
		return EndpointLoad{}, false
	}
	saturated, err := Resolve(Request{Harness: "fiz", Model: "model-b", CorrelationID: "bead-lease-1"}, saturatedInputs)
	if err != nil {
		t.Fatalf("Resolve(model-b with saturation): %v", err)
	}
	if saturated.ServerInstance != "server-b" {
		t.Fatalf("saturated decision server_instance=%q, want server-b because saturation outweighs sticky affinity", saturated.ServerInstance)
	}
	if saturated.Candidates[0].ServerInstance != "server-b" {
		t.Fatalf("saturated top candidate=%#v, want server-b", saturated.Candidates[0])
	}
	var saturatedSticky, saturatedNonSticky Candidate
	for _, c := range saturated.Candidates {
		switch c.ServerInstance {
		case "server-a":
			saturatedSticky = c
		case "server-b":
			saturatedNonSticky = c
		}
	}
	if !saturatedSticky.Eligible || !saturatedNonSticky.Eligible {
		t.Fatalf("saturated candidates must remain eligible for score comparison: %+v", saturated.Candidates)
	}
	if saturatedSticky.ScoreComponents["utilization"] >= saturatedNonSticky.ScoreComponents["utilization"] {
		t.Fatalf("saturated sticky utilization component=%v, want worse than non-sticky=%v", saturatedSticky.ScoreComponents["utilization"], saturatedNonSticky.ScoreComponents["utilization"])
	}
	if saturatedSticky.Score >= saturatedNonSticky.Score {
		t.Fatalf("saturated sticky score=%.2f should lose to non-sticky score=%.2f", saturatedSticky.Score, saturatedNonSticky.Score)
	}
}

// Decision is the routing engine's output: the picked candidate plus the
// full ranked list (including rejected ones with rejection reasons).
type Decision struct {
	Harness        string
	Provider       string
	Endpoint       string
	ServerInstance string
	Model          string
	Reason         string
	Candidates     []Candidate
}

// Candidate is one ranked routing option.
type Candidate struct {
	Harness            string
	Provider           string
	Endpoint           string
	ServerInstance     string
	Model              string
	Score              float64
	CostUSDPer1kTokens float64
	CostSource         string
	Power              int
	ContextLength      int
	ContextSource      string
	ScoreComponents    map[string]float64
	Eligible           bool
	Reason             string

	// FilterReason is the typed disqualification category, set at the
	// rejection site that decided why this candidate is ineligible.
	// Empty for eligible candidates. Service-layer code maps this to the
	// public FilterReason* string constants without parsing free-form
	// Reason text.
	FilterReason FilterReason

	// LatencyMS, SuccessRate, and CostClass expose the score-component
	// inputs so callers can render per-axis explanations alongside the
	// final Score. Zero / negative values mean unknown (see Inputs docs).
	LatencyMS       float64
	SuccessRate     float64
	CostClass       string
	SpeedTPS        float64
	Utilization     float64
	ContextHeadroom int

	QuotaOK          bool
	QuotaPercentUsed int
	QuotaTrend       string
	StickyAffinity   float64
}

// FilterReason categorizes why a routing candidate was disqualified.
// The zero value (empty string) means the candidate is eligible.
type FilterReason string

const (
	// FilterReasonEligible is the zero value for an eligible candidate.
	FilterReasonEligible FilterReason = ""
	// FilterReasonContextTooSmall: candidate's context window is below the
	// request's MinContextWindow().
	FilterReasonContextTooSmall FilterReason = "context_too_small"
	// FilterReasonNoToolSupport: request needs tool calling but candidate
	// does not support it.
	FilterReasonNoToolSupport FilterReason = "no_tool_support"
	// FilterReasonReasoningUnsupported: candidate cannot satisfy the
	// requested reasoning policy.
	FilterReasonReasoningUnsupported FilterReason = "reasoning_unsupported"
	// FilterReasonUnhealthy: harness/provider is unavailable, in cooldown,
	// out of quota, or excluded by a hard provider-preference gate.
	FilterReasonUnhealthy FilterReason = "unhealthy"
	// FilterReasonScoredBelowTop: catch-all for ineligibility that does
	// not fit a more specific category (also used for capability
	// mismatches such as permissions/model-pin/exact-pin and for model
	// resolution failures).
	FilterReasonScoredBelowTop FilterReason = "scored_below_top"
	// FilterReasonPinMismatch: candidate was rejected because it does not
	// satisfy an explicit caller pin such as Provider.
	FilterReasonPinMismatch FilterReason = "pin_mismatch"
	// FilterReasonPowerMissing: automatic routing requires catalog power
	// metadata, but the candidate model is unknown or has zero power.
	FilterReasonPowerMissing FilterReason = "power_missing"
	// FilterReasonBelowMinPower: candidate model power is below req.MinPower.
	FilterReasonBelowMinPower FilterReason = "below_min_power"
	// FilterReasonAboveMaxPower: candidate model power is above req.MaxPower.
	FilterReasonAboveMaxPower FilterReason = "above_max_power"
	// FilterReasonExactPinOnly: catalog marks the model as only eligible for
	// explicit model pins.
	FilterReasonExactPinOnly FilterReason = "exact_pin_only"
	// FilterReasonNotAutoRoutable: catalog metadata exists but marks the
	// model inactive, deprecated, stale, or otherwise excluded from
	// automatic routing.
	FilterReasonNotAutoRoutable FilterReason = "not_auto_routable"
	// FilterReasonQuotaExhausted: provider is in the quota_exhausted state
	// with retry_after in the future. The candidate would have been eligible
	// otherwise.
	FilterReasonQuotaExhausted FilterReason = "quota_exhausted"
)

// NoViableCandidateError reports that routing evaluated candidates but every
// one failed a gate.
type NoViableCandidateError struct {
	Rejected int
	Model    string
	Provider string
	Harness  string
	MinPower int
	MaxPower int
}

func (e *NoViableCandidateError) Error() string {
	var pins []string
	if e.Model != "" {
		pins = append(pins, "model="+e.Model)
	}
	if e.Provider != "" {
		pins = append(pins, "provider="+e.Provider)
	}
	if e.Harness != "" {
		pins = append(pins, "harness="+e.Harness)
	}
	if e.MinPower > 0 {
		pins = append(pins, fmt.Sprintf("min_power=%d", e.MinPower))
	}
	if e.MaxPower > 0 {
		pins = append(pins, fmt.Sprintf("max_power=%d", e.MaxPower))
	}
	if len(pins) > 0 {
		return fmt.Sprintf("no viable routing candidate for pins %s: %d candidates rejected", strings.Join(pins, " "), e.Rejected)
	}

	// quotaExhaustedRetryAfter is non-zero when this candidate would have been
	// eligible save for its provider being in the quota_exhausted state.
	// Resolve uses this to detect the "all eligible providers quota-exhausted"
	// case and surface ErrAllProvidersQuotaExhausted.
	quotaExhaustedRetryAfter time.Time
}

// buildHarnessCandidates expands one HarnessEntry into 1..N candidates, one
// per (harness, provider, resolved-model) tuple.
func buildHarnessCandidates(h HarnessEntry, req Request, in Inputs) []rankedCandidate {
	caps := Capabilities{
		SupportsTools:      h.SupportsTools,
		SupportedReasoning: h.SupportedReasoning,
		MaxReasoningTokens: h.MaxReasoningTokens,
		SupportedPerms:     h.SupportedPerms,
		ExactPinSupport:    h.ExactPinSupport,
		SupportedModels:    h.SupportedModels,
	}

	if !h.Available {
		return []rankedCandidate{{
			out: Candidate{
				Harness:      h.Name,
				CostSource:   CostSourceUnknown,
				Reason:       "harness not available",
				FilterReason: FilterReasonUnhealthy,
			},
			internal: candidateInternal{Harness: h.Name, CostClass: h.CostClass, CostSource: CostSourceUnknown},
		}}
	}

	histRate, hasHist := in.HistoricalSuccess[h.Name]
	if !hasHist {
		histRate = -1
	}

	// Enumerate providers. For harnesses with no providers (subprocess harnesses
	// with vendor-managed billing), emit a single virtual provider entry.
	providers := h.Providers
	if len(providers) == 0 {
		providers = []ProviderEntry{{Name: ""}}
	}

	out := make([]rankedCandidate, 0, len(providers))
	minCtx := req.MinContextWindow()
	stickyServerInstance := ""
	if req.CorrelationID != "" && in.StickyServerInstanceResolver != nil {
		stickyServerInstance, _ = in.StickyServerInstanceResolver(req.CorrelationID)
	}
	for _, p := range providers {
		model, reason := resolveModel(h, p, req, in)
		ctxWin := 0
		ctxSrc := ContextSourceUnknown
		if p.ContextWindows != nil {
			if v, ok := p.ContextWindows[model]; ok {
				ctxWin = v
			}
		}
		if ctxWin > 0 && p.ContextWindowSources != nil {
			if src, ok := p.ContextWindowSources[model]; ok && src != "" {
				ctxSrc = src
			}
		}
		if ctxWin == 0 && p.ContextWindow > 0 {
			ctxWin = p.ContextWindow
			if p.ContextWindowSource != "" {
				ctxSrc = p.ContextWindowSource
			}
		}
		if ctxWin == 0 && model != "" {
			ctxWin = 131072
			ctxSrc = ContextSourceDefault
		}
		if model == "" {
			ctxSrc = ContextSourceUnknown
		}
		entryCaps := caps
		entryCaps.ContextWindow = ctxWin
		entryCaps.SupportsTools = caps.SupportsTools || p.SupportsTools
		if len(p.DiscoveredIDs) > 0 {
			entryCaps.SupportedModels = nil
		}

		key := ProviderModelKey(p.Name, p.EndpointName, model)
		obs := in.ObservedSpeedTPS[key]
		if obs == 0 && p.EndpointName != "" {
			obs = in.ObservedSpeedTPS[ProviderModelKey(p.Name, "", model)]
		}
		providerSuccessRate := -1.0
		if rate, ok := in.ProviderSuccessRate[key]; ok {
			providerSuccessRate = rate
		} else if p.EndpointName != "" {
			if rate, ok := in.ProviderSuccessRate[ProviderModelKey(p.Name, "", model)]; ok {
				providerSuccessRate = rate
			}
		}
		latencyMS := in.ObservedLatencyMS[key]
		if latencyMS == 0 && p.EndpointName != "" {
			latencyMS = in.ObservedLatencyMS[ProviderModelKey(p.Name, "", model)]
		}
		power := candidatePower(in.ModelEligibility, model)
		endpointLoad := EndpointLoad{}
		if in.EndpointLoadResolver != nil {
			loadProvider, loadEndpoint := candidateLoadIdentity(h, p)
			if resolved, ok := in.EndpointLoadResolver(loadProvider, loadEndpoint, model); ok {
				endpointLoad = resolved
			}
		} else if load, ok := in.EndpointLoads[key]; ok {
			endpointLoad = load
		}

		gateReq := resolveRequestReasoning(req, h.Surface, in.ReasoningResolver)

		eligible := true
		var filterReason FilterReason
		if reason == "" {
			// Subscription quota is a hard availability gate and must be
			// reported before catalog metadata gates. An exhausted Claude/Codex/
			// Gemini account is never a viable candidate, regardless of whether
			// the resolved model has complete power metadata.
			if h.IsSubscription && !h.SubscriptionOK {
				eligible = false
				reason = h.QuotaReason
				if reason == "" {
					if h.QuotaStale {
						reason = "subscription quota unavailable"
					} else {
						reason = "subscription quota exhausted"
					}
				}
				filterReason = FilterReasonUnhealthy
			} else if g, fr := CheckPowerEligibility(in.ModelEligibility, model, gateReq); g != "" {
				eligible = false
				reason = g
				filterReason = fr
			} else if g, fr := CheckGating(entryCaps, gateReq); g != "" {
				eligible = false
				reason = g
				filterReason = fr
			}
		} else {
			eligible = false
			// resolveModel rejection — model resolution is a capability
			// mismatch with no specific public category, so fall through
			// to the catch-all.
			filterReason = FilterReasonScoredBelowTop
		}

		// Hard preference filtering.
		if eligible {
			switch req.ProviderPreference {
			case ProviderPreferenceLocalOnly:
				if !h.IsLocal {
					eligible = false
					reason = "preference is local-only"
					filterReason = FilterReasonUnhealthy
				}
			case ProviderPreferenceSubscriptionOnly:
				if !h.IsSubscription {
					eligible = false
					reason = "preference is subscription-only"
					filterReason = FilterReasonUnhealthy
				}
			}
		}

		if eligible && req.Provider != "" && req.Provider != candidateProviderIdentity(h, p) {
			// Hard provider pin: reject every other provider identity, even
			// when a non-pinned candidate would otherwise score higher.
			eligible = false
			reason = fmt.Sprintf("provider override requires %s", req.Provider)
			filterReason = FilterReasonPinMismatch
		}

		inCooldown := false
		if p.Name != "" && p.InCooldown {
			inCooldown = true
		} else if p.Name != "" && in.CooldownDuration > 0 {
			if failedAt, ok := in.ProviderCooldowns[p.Name]; ok {
				if in.Now.Sub(failedAt) < in.CooldownDuration {
					inCooldown = true
				}
			}
		}

		// Provider quota-exhausted gate. The state machine lives in the
		// service layer; the engine consumes the projected map of
		// provider-name → retry_after. Apply only when the candidate would
		// otherwise have been eligible — disqualifying an already-rejected
		// candidate with a different reason would lose the original signal.
		var quotaExhaustedRetryAfter time.Time
		if eligible {
			providerKey := candidateProviderIdentity(h, p)
			if providerKey != "" && len(in.ProviderQuotaExhaustedUntil) > 0 {
				if retryAfter, ok := in.ProviderQuotaExhaustedUntil[providerKey]; ok && retryAfter.After(in.Now) {
					eligible = false
					reason = fmt.Sprintf("provider %s quota exhausted until %s", providerKey, retryAfter.Format(time.RFC3339))
					filterReason = FilterReasonQuotaExhausted
					quotaExhaustedRetryAfter = retryAfter
				}
			}
		}

		stickyMatch := stickyServerInstance != "" && serverInstanceMatches(stickyServerInstance, p.ServerInstance, p.EndpointName)
		ci := candidateInternal{
			Harness:               h.Name,
			Provider:              p.Name,
			EndpointName:          p.EndpointName,
			ServerInstance:        p.ServerInstance,
			Model:                 model,
			CostClass:             candidateCostClass(h, p),
			CostUSDPer1kTokens:    p.CostUSDPer1kTokens,
			CostSource:            normalizeCostSource(p.CostSource),
			Power:                 power,
			ContextLength:         ctxWin,
			ContextSource:         ctxSrc,
			IsSubscription:        h.IsSubscription,
			QuotaOK:               h.QuotaOK,
			QuotaPercentUsed:      h.QuotaPercentUsed,
			QuotaStale:            h.QuotaStale,
			QuotaTrend:            h.QuotaTrend,
			SubscriptionOK:        h.SubscriptionOK,
			HistoricalSuccessRate: histRate,
			ProviderSuccessRate:   providerSuccessRate,
			ObservedTokensPerSec:  obs,
			ObservedLatencyMS:     latencyMS,
			InCooldown:            inCooldown || h.InCooldown,
			ProviderAffinityMatch: req.Provider != "" && req.Provider == candidateProviderIdentity(h, p),
			ProviderPreference:    req.ProviderPreference,
			EndpointLoad:          endpointLoad.NormalizedLoad,
			EndpointLoadFresh:     endpointLoad.UtilizationFresh,
			EndpointSaturated:     endpointLoad.UtilizationSaturated,
			StickyMatch:           stickyMatch,
		}
		if eligible && ctxWin > 0 && minCtx > 0 {
			ci.ContextHeadroom = ctxWin - minCtx
		}
		out = append(out, rankedCandidate{
			out: Candidate{
				Harness:            h.Name,
				Provider:           p.Name,
				Endpoint:           p.EndpointName,
				ServerInstance:     p.ServerInstance,
				Model:              model,
				CostUSDPer1kTokens: p.CostUSDPer1kTokens,
				CostSource:         normalizeCostSource(p.CostSource),
				Power:              power,
				ContextLength:      ctxWin,
				ContextSource:      ctxSrc,
				Eligible:           eligible,
				Reason:             reason,
				FilterReason:       filterReason,
				LatencyMS:          latencyMS,
				SuccessRate:        providerSuccessRate,
				CostClass:          candidateCostClass(h, p),
				SpeedTPS:           obs,
				Utilization:        endpointLoad.NormalizedLoad,
				ContextHeadroom:    ci.ContextHeadroom,
				QuotaOK:            h.QuotaOK,
				QuotaPercentUsed:   h.QuotaPercentUsed,
				QuotaTrend:         h.QuotaTrend,
				StickyAffinity: func() float64 {
					if stickyMatch {
						return StickyAffinityBonus
					}
					return 0
				}(),
			},
			internal:                 ci,
			quotaExhaustedRetryAfter: quotaExhaustedRetryAfter,
		})
	}
	return out
}

func candidatePower(lookup func(string) (ModelEligibility, bool), model string) int {
	if lookup == nil || model == "" {
		return 0
	}
	eligibility, ok := lookup(model)
	if !ok {
		return 0
	}
	return eligibility.Power
}

