func TestScorePowerSelectsPrepaidFrontierWhenQuotaHealthy(t *testing.T) {
	in := scorePowerInputs()

	dec, err := Resolve(Request{Profile: "smart"}, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
